    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        long[] nums = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            nums[i] = (long) in.nval;
        }
        long[] run = longestConsecutive(nums);
        StringBuilder sb = new StringBuilder();
        sb.append(run.length).append('\n');
        for (int i = 0; i < run.length; i++) sb.append(run[i]).append(i + 1 < run.length ? " " : "");
        sb.append('\n');
        System.out.print(sb);
    }
}
